var amountLarge = 45;
var gridSize = 5;
var minLength = 8;

// Colors
// let colorPalette = ["#f4d06f", "#ff8811", "#9dd9d2", "#676f54", "#392f5a"];
// let colorPalette = ["#4C2E05", "#7A8450", "#AEBD93", "#BEE7B8", "#E36397"];
let colorPalette = ["#4C2E05", "#7A8450", "#AEBD93", "#BEE7B8", "#E36397", "#db6800", "#e8ff81", "#29f0b6", "#531253", "#938ba1", "#ea3788"];
// let colorPalette = ["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"]; // genuary
// let bg = [124, 106, 119];
let bg_col = "rgb(124, 106, 119)"
let bg;
// let bg = [255, 255, 255];
// let bg = [0, 0, 0];

// Global variables
let initialCurves = [];
let finalCurves = [];

function setup() {
	createCanvas(dimx, dimy);
	colorMode(RGB);
	bg = color(bg_col);

	noStroke();
